package main

import (
	"fmt"
)

const MOD = 998244353

func modPow(a, e int64) int64 {
	res := int64(1)
	a %= MOD
	for e > 0 {
		if e&1 == 1 {
			res = (res * a) % MOD
		}
		a = (a * a) % MOD
		e >>= 1
	}
	return res
}

func modInv(a int64) int64 {
	return modPow(a, MOD-2)
}

func main() {
	var n, a, b int64
	fmt.Scan(&n, &a, &b)

	pless := a * modInv(b) % MOD
	pgreater := (b - a) * modInv(b) % MOD
	if pgreater < 0 {
		pgreater += MOD
	}

	// Precompute powers
	powPless := make([]int64, n+1)
	powPgreater := make([]int64, n+1)
	powPless[0] = 1
	powPgreater[0] = 1
	for i := int64(1); i <= n; i++ {
		powPless[i] = powPless[i-1] * pless % MOD
		powPgreater[i] = powPgreater[i-1] * pgreater % MOD
	}

	// CP table
	CP := make([][]int64, n+1)
	for i := int64(0); i <= n; i++ {
		CP[i] = make([]int64, n+1)
	}
	for i := int64(0); i <= n; i++ {
		for j := int64(0); j <= i; j++ {
			if j == 0 {
				CP[i][j] = 1
			} else {
				term1 := CP[i-1][j-1] * powPgreater[i-j] % MOD
				term2 := CP[i-1][j] * powPless[j] % MOD
				CP[i][j] = (term1 + term2) % MOD
			}
		}
	}

	// STRONG
	STRONG := make([]int64, n+1)
	for i := int64(0); i <= n; i++ {
		STRONG[i] = 1
		if i > 1 {
			for j := int64(1); j < i; j++ {
				STRONG[i] = (STRONG[i] - STRONG[j]*CP[i][j]%MOD + MOD) % MOD
			}
		}
	}

	// ans
	ans := make([]int64, n+1)
	for i := int64(2); i <= n; i++ {
		var sum int64
		for j := int64(1); j <= i; j++ {
			term := STRONG[j] * CP[i][j] % MOD
			inner := j*(i-j) + j*(j-1)/2
			if j < i {
				inner += ans[j]
			}
			inner += ans[i-j]
			inner %= MOD
			sum = (sum + term*inner) % MOD
		}
		coef := (1 - STRONG[i]*CP[i][i]%MOD + MOD) % MOD
		ans[i] = sum * modInv(coef) % MOD
	}

	fmt.Println(ans[n])
}
