package main

import (
	"fmt"
)

const MOD = 998244353

func bpow(a, b int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = int(int64(res) * int64(a) % MOD)
		}
		a = int(int64(a) * int64(a) % MOD)
		b >>= 1
	}
	return res
}

func main() {
	var n, a, b int
	fmt.Scan(&n, &a, &b)

	invB := bpow(b, MOD-2)
	pless := int(int64(a) * int64(invB) % MOD)
	pgreater := int(int64(b-a) * int64(invB) % MOD)

	CP := make([][]int, n+1)
	for i := range CP {
		CP[i] = make([]int, i+1)
	}

	for i := 0; i <= n; i++ {
		for j := 0; j <= i; j++ {
			if j == 0 {
				CP[i][j] = 1
			} else {
				term1 := int(int64(CP[i-1][j-1]) * int64(bpow(pgreater, i-j)) % MOD)
				term2 := int(int64(CP[i-1][j]) * int64(bpow(pless, j)) % MOD)
				CP[i][j] = term1 + term2
				if CP[i][j] >= MOD {
					CP[i][j] -= MOD
				}
			}
		}
	}

	STRONG := make([]int, n+1)
	for i := 0; i <= n; i++ {
		STRONG[i] = 1
		if i > 1 {
			for j := 1; j < i; j++ {
				STRONG[i] -= int(int64(STRONG[j]) * int64(CP[i][j]) % MOD)
				if STRONG[i] < 0 {
					STRONG[i] += MOD
				}
			}
		}
	}

	ans := make([]int, n+1)
	for i := 0; i <= n; i++ {
		if i < 2 {
			ans[i] = 0
		} else {
			sum := 0
			for j := 1; j <= i; j++ {
				term := int64(STRONG[j]) * int64(CP[i][j]) % MOD
				inner := j*(i-j) + j*(j-1)/2
				if j < i {
					inner += ans[j]
				}
				inner += ans[i-j]
				inner %= MOD
				sum = (sum + term*int64(inner)) % MOD
			}
			coef := 1 - int(int64(STRONG[i])*int64(CP[i][i])%MOD)
			if coef < 0 {
				coef += MOD
			}
			ans[i] = int(int64(sum) * int64(bpow(coef, MOD-2)) % MOD)
		}
	}

	fmt.Println(ans[n])
}

